import{_ as l,o,c as n,g as t}from"./chunks/framework.CNTkXYA8.js";const _=JSON.parse('{"title":"台风","description":"","frontmatter":{"title":"台风","date":"2026-08-28T11:07:00.000Z","draft":true,"tags":["小说","怪谈"]},"headers":[],"relativePath":"blog/typhoon.md","filePath":"source/_posts/typhoon.md"}'),p={name:"blog/typhoon.md"};function a(r,e,s,u,c,d){return o(),n("div",null,[...e[0]||(e[0]=[t("p",null,"我叫安德鲁·杰克，是一名学者。1927年，我在一个小地方读完博士，恰逢大萧条，我没有工作，贫困潦倒，一切全靠朋友接济。",-1),t("p",null,"在我发愁怎么解决下顿饭的那段时间，收到了一封来自朋友的、言辞恳切的信件，信件的内容如下，字迹有些潦草：",-1),t("p",null,"亲爱的安德鲁博士： 近来可好？愿你平安！我遇到了个麻烦。我有三名在行的船长，驾船在太平洋上运送茶叶和蔗糖，三天前，领头船在半途失去了联系。凭空在海面上消失了。无线电怎么也联系不到。 我的老友，如果有什么能帮到我的话，那一定是你渊博的知识、总是正确的判断。过几天，我会将打印的电讯航海日志邮寄给你。随信附15法郎。 愿你平安！ 匆忙的，金，1931月9月12日。",-1),t("p",null,"我的朋友，金，他和我在大学期间认识，有不错的交情。毕业之后，他没有继续读书，而是靠家里的钱买了一条单桅船，在印度和不列颠往返，做茶和糖的生意。很快，他拥有的就不只是一条船，而是二十多艘漂亮的双桅商船。尽管如此，如今他的日子也并不好过。",-1),t("p",null,"我在心里愉快地答应了他（并买了些吃的），过了几天，果然又有新的包裹邮到我的住处，里面附了一本笔记，是用工整的打印字体装订成册的，有油墨的香气。",-1),t("p",null,"我回到住处的书桌前，开始一页页翻阅这本笔记。书写者似乎是领头船的大副，我将有价值的部分摘抄如下：",-1),t("p",null,"7月20日，晴：我们从利物浦出发，准备在接下来三个月内绕过好望角，前往孟买。",-1),t("p",null,"7月23日，晴：离港3天，我们在船上再次检查货物，备用物资以及无线电通讯是否正常。 我们的货物有50箱绿茶茶叶，每箱173磅；76箱蔗糖，每箱235磅。 我们的备用物资有20桶淡水，5箱朗姆酒（给我省着点喝你们这群混蛋），20个柠檬，200磅法棍，2桶火药，以及7支抢，火绒若干。 与港口电台进行长波通讯：正常。 与2号船进行短波通讯：正常。 与3号船进行短波通讯：正常。",-1),t("p",null,"7月24日，阴：六分仪计算我们正处于北纬52度，东经73度，航速7海里。沿岸已经看不到陆地。",-1)])])}const f=l(p,[["render",a]]);export{_ as __pageData,f as default};
